import sys

def main():
    data = sys.stdin.read().split()
    n, target = int(data[0]), int(data[1])
    a = sorted(map(int, data[2:2 + n]))
    # pair
    lo, hi = 0, n - 1
    while lo < hi:
        s = a[lo] + a[hi]
        if s == target:
            print('YES')
            return
        if s < target:
            lo += 1
        else:
            hi -= 1
    # triplet
    for i in range(n - 2):
        need = target - a[i]
        lo, hi = i + 1, n - 1
        while lo < hi:
            s = a[lo] + a[hi]
            if s == need:
                print('YES')
                return
            if s < need:
                lo += 1
            else:
                hi -= 1
    print('NO')

